import React from 'react';
import { Box, TextField, Button, Typography, Paper, ButtonGroup } from '@mui/material';
import { reviewCode } from '../services/codeReviewService';

interface CodeEditorProps {
  taskDescription: string;
  onReviewComplete: (review: any) => void;
  onCodeChange: (code: string) => void;
  initialCode: string;
  onStatusChange: (status: 'completed' | 'failed' | 'abandoned') => void;
}

export const CodeEditor: React.FC<CodeEditorProps> = ({ 
  taskDescription, 
  onReviewComplete,
  onCodeChange,
  initialCode,
  onStatusChange
}) => {
  const [code, setCode] = React.useState(initialCode);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    setCode(initialCode);
  }, [initialCode]);

  const handleCodeChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newCode = e.target.value;
    setCode(newCode);
    onCodeChange(newCode);
  };

  const handleStatusChange = async (status: 'completed' | 'failed' | 'abandoned') => {
    if (!code.trim() && status === 'completed') {
      setError('Пожалуйста, введите код перед отправкой решения');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      if (status === 'completed') {
        const review = await reviewCode(code, taskDescription);
        onReviewComplete(review);
      }
      onStatusChange(status);
    } catch (error) {
      setError('Ошибка при проверке кода');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ mt: 2 }}>
      <Typography variant="h6" gutterBottom>
        Ваше решение:
      </Typography>
      <TextField
        multiline
        fullWidth
        rows={10}
        value={code}
        onChange={handleCodeChange}
        placeholder="Введите ваш код здесь..."
        sx={{
          '& .MuiInputBase-root': {
            fontFamily: 'monospace',
            fontSize: '14px',
          },
        }}
      />
      {error && (
        <Typography color="error" sx={{ mt: 1 }}>
          {error}
        </Typography>
      )}
      <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
        <ButtonGroup variant="contained" disabled={loading}>
          <Button
            color="success"
            onClick={() => handleStatusChange('completed')}
          >
            {loading ? 'Проверка...' : 'Решено'}
          </Button>
          <Button
            color="error"
            onClick={() => handleStatusChange('failed')}
          >
            Не решено
          </Button>
          <Button
            color="warning"
            onClick={() => handleStatusChange('abandoned')}
          >
            Пропустить
          </Button>
        </ButtonGroup>
      </Box>
    </Box>
  );
};
